 public sealed class CodexSessionSource : IDisposable {
 const int MaxBytes=1024*1024,BootstrapBytes=8*1024*1024;
 public string SelectedSourceId {get;set;} public int MaxDiscoverySources {get;set;} public int MaxPollBytes {get;set;}
 readonly string home; readonly JavaScriptSerializer json=new JavaScriptSerializer();
