 Dictionary<string,string> titleIndex=new Dictionary<string,string>(StringComparer.Ordinal);
 readonly HashSet<string> seenRequests=new HashSet<string>(StringComparer.Ordinal);readonly Queue<string> requestOrder=new Queue<string>();readonly SortedSet<string> requests=new SortedSet<string>(StringComparer.Ordinal);
