 DateTime discoveryUtc=DateTime.MinValue,rootStartedUtc=DateTime.MinValue,liveSince=DateTime.MinValue;string bootstrapLiveTurn=""; string path="",pending="";long offset,seq,baselineThrough=-1,currentRecordEnd;bool leaf,disposed,parseFailed,skipInitialLine,baselineReady;readonly List<MonitorTransition> deferredTransitions=new List<MonitorTransition>();int allowance,bytesRead;MonitorSnapshot state;
 public CodexSessionSource(string codexHome){home=codexHome;json.MaxJsonLength=BootstrapBytes;MaxDiscoverySources=128;MaxPollBytes=32*1024*1024;}
 static string S(Dictionary<string,object>d,string k){object v;return d!=null&&d.TryGetValue(k,out v)&&v is string?(string)v:"";}
 static Dictionary<string,object>D(Dictionary<string,object>d,string k){object v;return d!=null&&d.TryGetValue(k,out v)?v as Dictionary<string,object>:null;}
