 FileStream Open(string p){return new FileStream(p,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete);}
 Dictionary<string,object>Metadata(string p){using(var f=Open(p)){var b=new byte[(int)Math.Min(65536,f.Length)];int n=f.Read(b,0,b.Length);string text=Encoding.UTF8.GetString(b,0,n);int e=text.IndexOf('\n');return D(Parse(e>=0?text.Substring(0,e):text),"payload");}}
 IEnumerable<string>Find(){string dir=Path.Combine(home,"sessions");if(!Directory.Exists(dir))yield break;int limit=Math.Max(1,Math.Min(128,MaxDiscoverySources));var files=Directory.EnumerateFiles(dir,"*.jsonl",SearchOption.AllDirectories).Select(p=>new FileInfo(p)).OrderByDescending(f=>!String.IsNullOrEmpty(SelectedSourceId)&&f.Name.IndexOf(SelectedSourceId,StringComparison.OrdinalIgnoreCase)>=0).ThenByDescending(f=>f.LastWriteTimeUtc).Take(Math.Max(128,limit*4));int found=0;foreach(var file in files){bool valid=false;try{var meta=Metadata(file.FullName);valid=meta!=null&&D(meta,"source")==null&&S(meta,"originator")=="Codex Desktop";}catch(IOException){}catch(UnauthorizedAccessException){}if(valid){yield return file.FullName;if(++found>=limit)yield break;}}}
 void Reset(string p){path=p;offset=0;seq=0;pending="";baselineThrough=-1;baselineReady=false;deferredTransitions.Clear();skipInitialLine=false;seenRequests.Clear();requestOrder.Clear();bootstrapLiveTurn="";liveSince=DateTime.MinValue;ClearRequests();var meta=Metadata(p);state=new MonitorSnapshot{SourceId=S(meta,"id"),Detail="运行状态未知",IsCaughtUp=false};state.Title=Title(state.SourceId);}
 static DateTime EventTime(Dictionary<string,object>d){DateTime time;return DateTime.TryParse(S(d,"timestamp"),null,System.Globalization.DateTimeStyles.AssumeUniversal|System.Globalization.DateTimeStyles.AdjustToUniversal,out time)?time.ToUniversalTime():DateTime.MinValue;}
 static DateTime LastWrite(string p){try{return File.GetLastWriteTimeUtc(p);}catch{return DateTime.MinValue;}}
 public SourcePollResult Poll(DateTime nowUtc){if(!leaf)return PollAll(nowUtc);var result=new SourcePollResult();bytesRead=0;if(disposed){result.Health="读取器已关闭";return result;}state.Transitions.Clear();parseFailed=false;
 try{using(var f=Open(path)){if(f.Length<offset)Reset(path);if(baselineThrough<0){baselineThrough=f.Length;if(f.Length>BootstrapBytes){offset=f.Length-BootstrapBytes;skipInitialLine=true;}}
 long readStart=offset;int cap=offset<baselineThrough?BootstrapBytes:MaxBytes;int count=(int)Math.Min(Math.Min(cap,Math.Max(0,allowance)),f.Length-offset);f.Position=offset;byte[] b=new byte[count];int n=0,k;while(n<count&&(k=f.Read(b,n,count-n))>0)n+=k;offset+=n;bytesRead=n;
 long dataStart=readStart-Encoding.UTF8.GetByteCount(pending);string data=pending+Encoding.UTF8.GetString(b,0,n);int start=0;if(skipInitialLine){int e=data.IndexOf('\n');start=e<0?data.Length:e+1;if(e>=0)skipInitialLine=false;}long consumed=Encoding.UTF8.GetByteCount(data.Substring(0,start));int end;
 while((end=data.IndexOf('\n',start))>=0){string line=data.Substring(start,end-start);consumed+=Encoding.UTF8.GetByteCount(line)+1;currentRecordEnd=dataStart+consumed;Process(line);start=end+1;}pending=data.Substring(start);if(pending.Length>BootstrapBytes){pending="";parseFailed=true;state.Detail="记录行过长，运行状态未知";}state.IsCaughtUp=offset==f.Length&&pending.Length==0&&!parseFailed;if(!baselineReady&&offset>=baselineThrough&&offset-Encoding.UTF8.GetByteCount(pending)>=baselineThrough&&!parseFailed&&!skipInitialLine)baselineReady=true;}
 state.ObservedUtc=nowUtc;state.IsAvailable=baselineReady;if(!baselineReady){deferredTransitions.AddRange(state.Transitions);if(deferredTransitions.Count>512)deferredTransitions.RemoveRange(0,deferredTransitions.Count-512);state.Transitions.Clear();}else if(deferredTransitions.Count>0){state.Transitions.InsertRange(0,deferredTransitions);deferredTransitions.Clear();}var snapshot=Clone(state);if(!baselineReady)snapshot.Detail="正在同步历史运行记录";result.Snapshots.Add(snapshot);result.Health=!baselineReady?"正在同步历史运行记录":state.IsCaughtUp?"正在只读跟随 Codex 桌面聊天":"正在追赶记录或等待完整记录行";
 }catch(Exception ex){result.Health="读取异常："+ex.GetType().Name;var copy=Clone(state);copy.IsAvailable=false;copy.IsCaughtUp=false;copy.ObservedUtc=nowUtc;result.Snapshots.Add(copy);}return result;}
 SourcePollResult PollAll(DateTime now){bool firstRootPoll=rootStartedUtc==DateTime.MinValue;if(firstRootPoll)rootStartedUtc=now;var result=new SourcePollResult();if(disposed){result.Health="读取器已关闭";return result;}string issue="";
 if(discoveryUtc==DateTime.MinValue||now-discoveryUtc>=TimeSpan.FromSeconds(10)){discoveryUtc=now;ReadTitleIndex();try{var candidates=Find().ToList();int capacity=Math.Max(1,Math.Min(128,MaxDiscoverySources));foreach(string candidate in candidates){if(tracked.ContainsKey(candidate))continue;if(tracked.Count>=capacity){var victim=tracked.Where(x=>x.Value.state.SourceId!=SelectedSourceId).OrderBy(x=>candidates.Contains(x.Key)).ThenBy(x=>x.Value.state.IsGenerating).ThenBy(x=>LastWrite(x.Key)).FirstOrDefault();if(victim.Key==null){issue="监控容量已满，保留已选聊天";continue;}victim.Value.Dispose();tracked.Remove(victim.Key);issue="监控范围限最近"+capacity+"个桌面聊天，旧历史已移出";}try{var source=new CodexSessionSource(home);source.leaf=true;source.titleIndex=titleIndex;source.Reset(candidate);if(!firstRootPoll)source.liveSince=rootStartedUtc;tracked.Add(candidate,source);}catch(Exception ex){issue="发现记录读取异常："+ex.GetType().Name;}}}catch(Exception ex){issue="发现记录读取异常："+ex.GetType().Name;}foreach(var source in tracked.Values){source.titleIndex=titleIndex;source.state.Title=source.Title(source.state.SourceId);}}
 int remaining=Math.Max(MaxBytes,Math.Min(128*1024*1024,MaxPollBytes));foreach(var source in tracked.Values.OrderByDescending(x=>x.state.SourceId==SelectedSourceId).ThenByDescending(x=>LastWrite(x.path)).ToList()){source.allowance=remaining;var poll=source.Poll(now);remaining=Math.Max(0,remaining-source.bytesRead);result.Snapshots.AddRange(poll.Snapshots);if(poll.Snapshots.Any(x=>!x.IsAvailable&&x.Detail!="正在同步历史运行记录"))issue="部分聊天记录不可用";else if(poll.Snapshots.Any(x=>!x.IsAvailable&&x.Detail=="正在同步历史运行记录")&&issue.Length==0)issue="正在同步历史运行记录";}
 result.Health=issue.Length>0?issue:result.Snapshots.Count==0?"未找到 Codex 桌面聊天记录":"正在只读跟随 "+result.Snapshots.Count+" 个 Codex 桌面聊天（上限"+Math.Max(1,Math.Min(128,MaxDiscoverySources))+"）";return result;}
 static MonitorSnapshot Clone(MonitorSnapshot s){return new MonitorSnapshot{SourceId=s.SourceId,Title=s.Title,TurnId=s.TurnId,TurnTrigger=s.TurnTrigger,Fingerprint=s.Fingerprint,AttentionId=s.AttentionId,AttentionUtc=s.AttentionUtc,ObservedUtc=s.ObservedUtc,LastActivityUtc=s.LastActivityUtc,EndedUtc=s.EndedUtc,IsAvailable=s.IsAvailable,IsGenerating=s.IsGenerating,NeedsInput=s.NeedsInput,HasError=s.HasError,ExplicitCompleted=s.ExplicitCompleted,WasInterrupted=s.WasInterrupted,Detail=s.Detail,PendingRequestIds=new List<string>(s.PendingRequestIds),HasBlockingInput=s.HasBlockingInput,IsCaughtUp=s.IsCaughtUp,Transitions=s.Transitions.Select(x=>new MonitorTransition{Id=x.Id,TurnId=x.TurnId,TurnTrigger=x.TurnTrigger,RequestId=x.RequestId,Kind=x.Kind,OccurredUtc=x.OccurredUtc}).ToList()};}
 void Emit(MonitorTransitionKind kind,Dictionary<string,object>d,string requestId=""){if(currentRecordEnd<=baselineThrough&&(liveSince==DateTime.MinValue||bootstrapLiveTurn!=state.TurnId||EventTime(d)<liveSince))return;state.Transitions.Add(new MonitorTransition{Id=state.SourceId+":"+currentRecordEnd+":"+seq+":"+kind,TurnId=state.TurnId,TurnTrigger=state.TurnTrigger,RequestId=requestId,Kind=kind,OccurredUtc=EventTime(d)});}
 void Process(string line){if(String.IsNullOrWhiteSpace(line))return;var d=Parse(line);if(d==null){parseFailed=true;return;}var p=D(d,"payload");if(p==null)return;string type=S(d,"type"),kind=S(p,"type"),turn=S(p,"turn_id"),root=S(p,"root_turn_id");bool meaningful=false;
 if(type=="event_msg"){
 if(kind=="task_started"){if(root.Length>0&&turn.Length>0&&root!=turn)return;ClearRequests();state.EndedUtc=DateTime.MinValue;state.IsGenerating=true;state.ExplicitCompleted=false;state.HasError=false;state.WasInterrupted=false;state.TurnId=turn;state.TurnTrigger=S(D(p,"turn_attribution"),"turn_trigger");bootstrapLiveTurn=liveSince!=DateTime.MinValue&&EventTime(d)>=liveSince?turn:"";state.Detail="正在生成";Emit(MonitorTransitionKind.Working,d);meaningful=true;}
 else if(kind=="task_complete"||kind=="turn_aborted"){if(root.Length>0&&root!=turn)return;if(state.TurnId.Length==0&&currentRecordEnd<=baselineThrough)state.TurnId=turn;if(turn.Length==0||state.TurnId!=turn)return;state.IsGenerating=false;state.EndedUtc=EventTime(d);state.WasInterrupted=kind=="turn_aborted";state.ExplicitCompleted=kind=="task_complete"&&!state.HasError;state.Detail=state.WasInterrupted?"生成已中断":state.HasError?"执行失败":state.NeedsInput?"等待回答":"生成结束";Emit(state.WasInterrupted?MonitorTransitionKind.Interrupted:state.HasError?MonitorTransitionKind.Error:state.NeedsInput?MonitorTransitionKind.NeedsInput:MonitorTransitionKind.Completed,d);meaningful=true;}
 else if(kind=="exec_approval_request"||kind=="apply_patch_approval_request"||kind=="request_permissions"){Request(p,d,"approval");meaningful=true;}
 else if(kind=="request_user_input"){Request(p,d,"sync");meaningful=true;}
 else if(kind=="exec_command_begin"||kind=="patch_apply_begin"){Resolve(S(p,"call_id"),"approval",d);meaningful=true;}
 else if(kind=="error"){state.HasError=true;state.AttentionUtc=EventTime(d);state.AttentionId="error:"+S(d,"timestamp")+":"+(seq+1);state.Detail="执行发生错误，运行状态未结束";meaningful=true;}
 else if(kind=="user_message"){bool blocked=state.HasBlockingInput;ClearRequests();if(blocked&&state.IsGenerating)Emit(MonitorTransitionKind.Working,d);meaningful=true;}
 else if(kind=="agent_message"||kind=="agent_reasoning"||kind=="token_count"||kind=="item_completed"||kind=="item_started")meaningful=true;
 }else if(type=="response_item"){
 if(kind=="function_call"||kind=="custom_tool_call"){string name=S(p,"name");if(name.EndsWith("request_user_input_async",StringComparison.Ordinal)||name.EndsWith("request_user_input",StringComparison.Ordinal))Request(p,d,name.EndsWith("request_user_input_async",StringComparison.Ordinal)?"async":"sync");meaningful=true;}
 else if(kind=="function_call_output"||kind=="custom_tool_call_output"){var output=D(p,"output")??Parse(S(p,"output"));object answers;var collection=output!=null&&output.TryGetValue("answers",out answers)?answers as System.Collections.ICollection:null;if(collection!=null&&collection.Count>0){string requestKind;if(requestKinds.TryGetValue(S(p,"call_id"),out requestKind)&&(requestKind=="sync"||requestKind=="async"))Resolve(S(p,"call_id"),requestKind,d);}meaningful=true;}
 else if(kind=="reasoning"||kind=="agent_message")meaningful=true;
 else if(kind=="message"){if(S(p,"role")=="user"){bool blocked=state.HasBlockingInput;ClearRequests();if(blocked&&state.IsGenerating)Emit(MonitorTransitionKind.Working,d);state.Detail=state.IsGenerating?"正在生成":"运行状态未知";}meaningful=true;}}
 if(meaningful){DateTime ts=EventTime(d);if(ts!=DateTime.MinValue)state.LastActivityUtc=ts;state.Fingerprint=state.SourceId+":"+currentRecordEnd+":"+(++seq);}}
 void Request(Dictionary<string,object>p,Dictionary<string,object>d,string requestKind){string id=S(p,"call_id");if(id.Length==0)id=S(p,"id");if(id.Length==0)id=S(p,"type")+":"+S(d,"timestamp");if(!requests.Contains(id)&&seenRequests.Contains(id))return;bool before=state.HasBlockingInput;bool added=requests.Add(id);if(added){requestKinds[id]=requestKind;requestTimes[id]=EventTime(d);if(seenRequests.Add(id)){requestOrder.Enqueue(id);while(requestOrder.Count>1024)seenRequests.Remove(requestOrder.Dequeue());}Emit(MonitorTransitionKind.InputRequested,d,id);}RefreshRequests();if(!before&&state.HasBlockingInput&&state.IsGenerating)Emit(MonitorTransitionKind.NeedsInput,d);}
 void RefreshRequests(){state.PendingRequestIds=requests.ToList();state.NeedsInput=requests.Count>0;state.HasBlockingInput=requestKinds.Values.Any(x=>x!="async");state.AttentionId=String.Join("|",requests);state.AttentionUtc=requestTimes.Count>0?requestTimes.Values.Max():DateTime.MinValue;state.Detail=state.HasBlockingInput?(requestKinds.Values.Any(x=>x=="approval")?"等待授权":"等待回答"):state.IsGenerating?"正在生成":state.NeedsInput?"等待回答":state.ExplicitCompleted?"生成结束":"运行状态未知";}
 void Resolve(string id,string expected,Dictionary<string,object>d){string kind;if(id.Length==0||!requestKinds.TryGetValue(id,out kind)||kind!=expected)return;bool blocked=state.HasBlockingInput;requests.Remove(id);requestKinds.Remove(id);requestTimes.Remove(id);RefreshRequests();if(blocked&&!state.HasBlockingInput&&state.IsGenerating)Emit(MonitorTransitionKind.Working,d);}
 void ClearRequests(){requests.Clear();requestKinds.Clear();requestTimes.Clear();if(state!=null){state.PendingRequestIds.Clear();state.NeedsInput=false;state.HasBlockingInput=false;state.AttentionId="";state.AttentionUtc=DateTime.MinValue;}}
 public void Dispose(){disposed=true;pending="";foreach(var source in tracked.Values)source.Dispose();tracked.Clear();}
 string Title(string id){string indexed;if(titleIndex.TryGetValue(id,out indexed))return indexed;try{string p=Path.Combine(home,".codex-global-state.json");var fi=new FileInfo(p);if(fi.Exists&&fi.Length<4*1024*1024){using(var f=Open(p))using(var r=new StreamReader(f)){var d=Parse(r.ReadToEnd());var titles=D(d,"thread-titles");string t=S(titles,id);if(t.Length==0)t=S(D(titles,"titles"),id);if(t.Length>0)return t.Substring(0,Math.Min(60,t.Length)).Replace('\r',' ').Replace('\n',' ');}}}catch{}return "Codex 聊天 "+id.Substring(0,Math.Min(8,id.Length));}

 void ReadTitleIndex(){try{string index=Path.Combine(home,"session_index.jsonl");if(!File.Exists(index))return;var cache=new Dictionary<string,string>(StringComparer.Ordinal);using(var f=Open(index)){const int limit=4*1024*1024;bool skip=f.Length>limit;if(skip)f.Position=f.Length-limit;byte[] b=new byte[(int)Math.Min(limit,f.Length)];int n=0,k;while(n<b.Length&&(k=f.Read(b,n,b.Length-n))>0)n+=k;string[] lines=Encoding.UTF8.GetString(b,0,n).Split('\n');for(int i=skip?1:0;i<lines.Length&&i<32768;i++){var entry=Parse(lines[i]);string id=S(entry,"id"),title=S(entry,"thread_name");if(id.Length==0||title.Length==0)continue;cache[id]=title.Substring(0,Math.Min(60,title.Length)).Replace('\r',' ').Replace('\n',' ');}}titleIndex=cache;}catch(IOException){}catch(UnauthorizedAccessException){}}

 }
